function stripslashes_deep($value) {
       if( is_array($value) )
       {
             $value = array_map('stripslashes_deep', $value);
       }
       elseif ( !empty($value) && is_string($value) )
       {
             $value = stripslashes($value);
       }
       return $value;
   }
